/* quiz-flashcards.js - 313 Q&A cards imported from the user's tracked-edits notes,
 * appended to the seed flashcard bank. Study aid only; verify against guidelines. */
window.BCEMP_FLASHCARDS = (window.BCEMP_FLASHCARDS || []).concat([
  { id: "qc-0", domain: "pmr", front: "Study reports HR 0.85 (95% CI 0.72-0.98) for new drug vs control on mortality. Interpretation?", back: "Statistically significant 15% reduction in mortality hazard with new drug. CI doesn't cross 1 → significant. CI 0.72-0.98 = wide-ish, modest precision", tags: ["biostats"] },
  { id: "qc-1", domain: "pmr", front: "RCT reports ARR 4% with p=0.04. NNT?", back: "NNT = 1/ARR = 1/0.04 = 25. Round UP. So 25 patients treated to prevent one bad outcome. Pair with NNH for harms to assess net benefit", tags: ["biostats"] },
  { id: "qc-2", domain: "pmr", front: "Sensitivity 95%, specificity 80%. LR+ and LR−?", back: "LR+ = 0.95/(1−0.80) = 4.75. LR− = (1−0.95)/0.80 = 0.0625. LR− < 0.1 = strong rule-out test when negative", tags: ["biostats"] },
  { id: "qc-3", domain: "pmr", front: "Why is ITT preferred in superiority trials?", back: "Preserves randomization → unbiased treatment estimate. Maintains Type I error. Reflects \"effectiveness\" — real-world outcomes including non-adherence + dropouts", tags: ["biostats"] },
  { id: "qc-4", domain: "pmr", front: "Why is per-protocol required in noninferiority?", back: "ITT tends to bias toward null (no difference) — but in noninferiority, null = inferiority. So ITT alone could FALSELY conclude noninferiority. Both ITT and PP must show NI", tags: ["biostats"] },
  { id: "qc-5", domain: "pmr", front: "Meta-analysis shows I² = 78%. Interpretation?", back: "Considerable heterogeneity — pooled estimate is less reliable. Explore sources via subgroup analyses or meta-regression. Consider random-effects model. Maybe don't pool at all", tags: ["biostats"] },
  { id: "qc-6", domain: "pmr", front: "Study reports OR 3.5 for smoking and lung cancer, but baseline lung cancer rate is 50%. Compare to RR?", back: "OR overestimates RR when outcome is common. RR would be much closer to 1. OR ≈ RR only for rare outcomes < 10%", tags: ["biostats"] },
  { id: "qc-7", domain: "pmr", front: "Crossover trial design considerations?", back: "Each patient is own control → smaller n needed. REQUIRES washout period (5 half-lives). NOT suitable for diseases with progression or irreversible effects. Carryover effects threaten validity", tags: ["biostats"] },
  { id: "qc-8", domain: "pmr", front: "Block randomization with block size 4 — how it works?", back: "Each block of 4 contains 2 A and 2 B assignments in random order. Ensures balance across enrollment. NOT \"first 4 get A, next 4 get B\" — that's sequential, not random", tags: ["biostats"] },
  { id: "qc-9", domain: "pmr", front: "ARR vs RR difference? Trial drug 2% mortality vs placebo 4%. ARR vs RRR?", back: "ARR = 4% − 2% = 2 percentage points. RRR = (1 − 0.5) × 100% = 50%. Same data, RRR sounds more impressive — be aware of presentation framing", tags: ["biostats"] },
  { id: "qc-10", domain: "pmr", front: "Funnel plot is asymmetric, missing small negative studies on one side. Interpretation?", back: "Suggests PUBLICATION BIAS — small \"negative\" studies less likely to be published. Egger's test formally evaluates. Use trim-and-fill or other adjustment methods", tags: ["biostats"] },
  { id: "qc-11", domain: "pmr", front: "Type I vs Type II error?", back: "Type I = reject H0 when true (false positive, α). Type II = fail to reject when false (false negative, β). Power = 1 − β", tags: ["biostats"] },
  { id: "qc-12", domain: "pmr", front: "Power = 80%, α = 0.05. What if you want to detect smaller effect?", back: "Need LARGER sample size. Power depends on n, effect size, variability, α", tags: ["biostats"] },
  { id: "qc-13", domain: "pmr", front: "Pharmacist precepting resident who is competent with workflow but still asks confirmation on every plan. What stage?", back: "Coaching → Facilitating transition. Resident isn't ready for full independence yet, but moving toward Facilitating. Continue observing + reduce involvement gradually", tags: ["biostats"] },
  { id: "qc-14", domain: "pmr", front: "Sentinel event occurs — patient received 10× insulin dose. Process?", back: "Root Cause Analysis (RCA). Use \"5 Whys\" + fishbone diagram. Joint Commission requires within 45 days. Apply JUST CULTURE framework — was this human error, at-risk, or reckless?", tags: ["biostats"] },
  { id: "qc-15", domain: "pmr", front: "Pre-test probability 20%, test LR+ = 10. Post-test probability?", back: "Pre-test odds = 0.20/0.80 = 0.25. Post-test odds = 0.25 × 10 = 2.5. Post-test prob = 2.5/3.5 = 71%. Test changed probability substantially", tags: ["biostats"] },
  { id: "qc-16", domain: "pmr", front: "Investigational drug for cardiac arrest — can it be given without informed consent?", back: "Yes, with EFIC waiver per 21 CFR 50.24: life-threatening condition + unproven treatments + need data + consent not feasible + community consultation prior. Common in arrest research", tags: ["biostats"] },
  { id: "qc-17", domain: "pmr", front: "GRADE evidence quality for RCT with imprecision + indirectness — final rating?", back: "Start at HIGH for RCT. Downgrade for imprecision (CI crosses clinical decision threshold) → MODERATE. Downgrade for indirectness (population/intervention different from clinical question) → LOW", tags: ["biostats"] },
  { id: "qc-18", domain: "pmr", front: "Hospital reports adverse drug event rate dropped from 2% to 0.5% after intervention. Run chart shows 8 consecutive points below mean. Interpretation?", back: "Special-cause variation suggesting real improvement. Statistical Process Control rules — 8 consecutive points one side of mean indicates non-random shift", tags: ["biostats"] },
  { id: "qc-19", domain: "resus", front: "Refractory VF after 3 shocks — next best step?", back: "Answer: change vector / DSED, switch antiarrhythmic, consider esmolol, activate ECPR pathway. DOSE-VF trial", tags: ["cards_arrest"] },
  { id: "qc-20", domain: "resus", front: "Patient in arrest with K = 7.2 on ABG. Order of interventions?", back: "Calcium FIRST for membrane stabilization, then bicarb, then insulin/D50. NOT albuterol in arrest — too slow", tags: ["cards_arrest"] },
  { id: "qc-21", domain: "resus", front: "Post-ROSC patient with PaO₂ of 340 — what to adjust?", back: "Wean FiO₂ to target SpO₂ 92–98%; hyperoxia worsens neuro outcomes", tags: ["cards_arrest"] },
  { id: "qc-22", domain: "resus", front: "Suspected massive PE arrest — alteplase dose?", back: "50 mg IV push, may repeat 50 mg in 15 min if no ROSC. Continue CPR 60–90 min after lysis", tags: ["cards_arrest"] },
  { id: "qc-23", domain: "resus", front: "Patient post-ROSC with STEMI on ECG vs no STEMI — cath lab?", back: "STEMI YES emergent. No STEMI without instability — COACT/TOMAHAWK say no rush, can wait for clinical picture", tags: ["cards_arrest"] },
  { id: "qc-24", domain: "resus", front: "BB toxicity vs CCB toxicity glucose pattern?", back: "BB → HYPOglycemia from blocked β2 glycogenolysis. CCB → HYPERglycemia from blocked insulin release. HIE works for both via inotropy", tags: ["cards_arrest"] },
  { id: "qc-25", domain: "resus", front: "PALS: 6-year-old in PEA, K = 6.5, ECG shows wide QRS. Initial drug?", back: "Calcium chloride 20 mg/kg IV push for hyperK membrane stabilization, alongside CPR + epi", tags: ["cards_arrest"] },
  { id: "qc-26", domain: "resus", front: "Patient codes on the floor; AMS noted before arrest with pinpoint pupils. Adjunct to ACLS?", back: "Naloxone 2–4 mg IN or 0.4–2 mg IV — but do NOT delay compressions/epi/defib", tags: ["cards_arrest"] },
  { id: "qc-27", domain: "resus", front: "EtCO₂ has been 8 mmHg for 22 minutes of high-quality CPR — what does this mean?", back: "Poor prognosis; reasonable to consider termination if no reversible cause being addressed", tags: ["cards_arrest"] },
  { id: "qc-28", domain: "resus", front: "ECPR candidate criteria?", back: "Witnessed arrest, initial shockable rhythm, no ROSC after 3 shocks, low-flow <30–60 min, age ≤75, no severe comorbidity. ARREST trial", tags: ["cards_arrest"] },
  { id: "qc-29", domain: "resus", front: "In-hospital cardiac arrest — additional consideration per VAM-IHCA?", back: "Methylprednisolone 40 mg IV + vasopressin 20 IU per epi dose, Class 2b", tags: ["cards_arrest"] },
  { id: "qc-30", domain: "resus", front: "Why hold epi in first 2 min after defib for shockable rhythm?", back: "Early epi associated with worse neuro outcomes in shockable rhythms; defib + CPR alone may achieve ROSC without catecholamine surge", tags: ["cards_arrest"] },
  { id: "qc-31", domain: "derm", front: "Patient on simvastatin started on clarithromycin develops a gout flare. Drug to AVOID for treatment?", back: "Colchicine — clarithromycin is a strong CYP3A4/P-gp inhibitor; colchicine + statin + clarithromycin = rhabdo + colchicine toxicity risk. Use steroids instead", tags: ["derm"] },
  { id: "qc-32", domain: "derm", front: "Han Chinese patient with newly diagnosed gout — what to do before starting allopurinol?", back: "Screen HLA-B*5801; if positive, use febuxostat or probenecid instead", tags: ["derm"] },
  { id: "qc-33", domain: "derm", front: "Patient on allopurinol 100 mg gets uric acid 7.5 mg/dL after 3 months. Next step?", back: "Titrate up — target <6 mg/dL; allopurinol can go to 800 mg/day if tolerated. Continue anti-inflammatory ppx", tags: ["derm"] },
  { id: "qc-34", domain: "derm", front: "Why does febuxostat have a black box warning?", back: "CARES trial — increased CV and all-cause mortality vs allopurinol. Reserve for allopurinol intolerance", tags: ["derm"] },
  { id: "qc-35", domain: "derm", front: "BSA cutoffs for SJS, overlap, TEN?", back: "<10% SJS, 10–30% overlap, >30% TEN", tags: ["derm"] },
  { id: "qc-36", domain: "derm", front: "SCORTEN day 1 = 3 — mortality estimate and disposition?", back: "~36% mortality; burn ICU", tags: ["derm"] },
  { id: "qc-37", domain: "derm", front: "Best-evidence adjunct in TEN per 2024 data?", back: "Cyclosporine 3–5 mg/kg/day; etanercept 50 mg SC ×1 as alternative. NOT IVIG anymore", tags: ["derm"] },
  { id: "qc-38", domain: "derm", front: "Patient develops fever, morbilliform rash, eosinophilia, transaminitis 5 weeks after starting carbamazepine. Diagnosis?", back: "DRESS — note the long latency 2–8 wk vs SJS/TEN 1–4 wk; eosinophilia is the giveaway. Tx: stop drug, systemic steroids with slow taper", tags: ["derm"] },
  { id: "qc-39", domain: "derm", front: "Why avoid silver sulfadiazine in TEN?", back: "Sulfonamide cross-reactivity if sulfa was the inciting drug. Use silver-impregnated dressings instead", tags: ["derm"] },
  { id: "qc-40", domain: "derm", front: "TEN patient with 50% BSA detachment — fluid resuscitation formula?", back: "2 mL/kg/%BSA in 24 hr — LESS than Parkland's 4 mL/kg/%BSA for burns. Over-resuscitation causes harm", tags: ["derm"] },
  { id: "qc-41", domain: "derm", front: "Patient with HIV starting abacavir — required pre-screening?", back: "HLA-B*5701; if positive, do NOT use abacavir", tags: ["derm"] },
  { id: "qc-42", domain: "derm", front: "Distinguish SJS/TEN from staph scalded skin syndrome on exam?", back: "SSSS SPARES mucosa, peds predominant, exfoliative toxin-mediated; SJS/TEN has prominent mucosal involvement at ≥2 sites", tags: ["derm"] },
  { id: "qc-43", domain: "derm", front: "Patient with rash + pustules 24 hr after starting amoxicillin, no mucosal involvement. Diagnosis?", back: "AGEP — rapid onset <48 hr distinguishes from SJS/TEN; sterile pustules; self-limited", tags: ["derm"] },
  { id: "qc-44", domain: "derm", front: "Pseudogout vs gout on synovial fluid microscopy?", back: "Gout = needle-shaped, NEGATIVELY birefringent MSU crystals. Pseudogout = rhomboid, POSITIVELY birefringent CPPD crystals", tags: ["derm"] },
  { id: "qc-45", domain: "endo", front: "DKA patient, glucose now 220, gap still 18. Next step?", back: "ADD dextrose, CONTINUE insulin — never stop insulin until gap closes", tags: ["endo"] },
  { id: "qc-46", domain: "endo", front: "DKA patient K = 3.1 before treatment. Next step?", back: "Hold insulin, replete K to >3.3 first — insulin would cause fatal hypoK", tags: ["endo"] },
  { id: "qc-47", domain: "endo", front: "Why is balanced crystalloid now preferred over NS in DKA?", back: "Less hyperchloremic metabolic acidosis, faster gap closure — PLUS-DKA/SCOPE-DKA", tags: ["endo"] },
  { id: "qc-48", domain: "endo", front: "8-year-old in DKA develops headache + bradycardia + rising BP 6 hr into treatment. Diagnosis + immediate action?", back: "Cerebral edema → mannitol 0.5–1 g/kg or 3% saline, reduce fluids, elevate HOB — do NOT wait for CT", tags: ["endo"] },
  { id: "qc-49", domain: "endo", front: "Patient on empagliflozin, glucose 180, pH 7.1, gap 22. Diagnosis?", back: "Euglycemic DKA — treat with insulin + dextrose; can persist for days", tags: ["endo"] },
  { id: "qc-50", domain: "endo", front: "HHS vs DKA — which gets bicarb, which needs slower correction?", back: "HHS: no bicarb, correct osm slower; DKA: also generally no bicarb per 2024", tags: ["endo"] },
  { id: "qc-51", domain: "endo", front: "Thyroid storm — correct order of the first two drugs?", back: "β-blocker for symptoms, then thionamide BEFORE iodine; iodine ≥1 hr after thionamide", tags: ["endo"] },
  { id: "qc-52", domain: "endo", front: "Why give iodine AFTER, not before, thionamide in storm?", back: "Jod-Basedow — iodine alone is substrate for new hormone synthesis; must block synthesis first", tags: ["endo"] },
  { id: "qc-53", domain: "endo", front: "Is radioactive iodine used in thyroid storm?", back: "NO — contraindicated; that's I-131 outpatient Graves therapy. Storm uses cold SSKI/Lugol's", tags: ["endo"] },
  { id: "qc-54", domain: "endo", front: "Patient on amiodarone develops thyrotoxicosis; Doppler shows LOW vascularity. Type and treatment?", back: "Type 2 destructive → steroids. Type 1 = high vascularity → thionamides", tags: ["endo"] },
  { id: "qc-55", domain: "endo", front: "Myxedema coma — give thyroid hormone or steroid first?", back: "STEROID first — hydrocortisone — to avoid precipitating adrenal crisis", tags: ["endo"] },
  { id: "qc-56", domain: "endo", front: "Adrenal crisis electrolytes?", back: "HypoNa + HYPERK + hypoglycemia. Primary = high ACTH + hyperpigmentation; secondary = low ACTH, aldosterone spared", tags: ["endo"] },
  { id: "qc-57", domain: "endo", front: "Why is hydrocortisone preferred over dexamethasone in adrenal crisis?", back: "Stress-dose hydrocortisone has intrinsic mineralocorticoid activity; dex does not", tags: ["endo"] },
  { id: "qc-58", domain: "endo", front: "Pheochromocytoma patient — which blocker first?", back: "ALPHA before beta — unopposed alpha → hypertensive crisis if β given first", tags: ["endo"] },
  { id: "qc-59", domain: "endo", front: "Post-SAH patient with hyponatremia and hypovolemia. SIADH or CSW, and how does treatment differ?", back: "CSW — give salt + volume; SIADH would be fluid restriction. Volume status distinguishes", tags: ["endo"] },
  { id: "qc-60", domain: "endo", front: "Hypercalcemic crisis first-line treatment?", back: "Aggressive IV saline, then calcitonin for speed, then bisphosphonate for durability. Loops only if volume overloaded", tags: ["endo"] },
  { id: "qc-61", domain: "env", front: "Rattlesnake bite with progressive swelling + INR 2.5 + fibrinogen 80. Antivenom choice + dosing?", back: "CroFab 4-6 vials initial control, or 10 vials ANAVIP. Continue until control achieved [no progression + coag normalizing]. CroFab needs scheduled maintenance q6h × 3; ANAVIP does NOT routine maintenance, just monitor 18 hr", tags: ["envtox"] },
  { id: "qc-62", domain: "env", front: "Copperhead bite with mild local swelling, no systemic signs, 8 hr post-bite. Antivenom?", back: "Likely not needed — mild copperhead envenomation often resolves with supportive care alone. Reserve for progressive symptoms", tags: ["envtox"] },
  { id: "qc-63", domain: "env", front: "Coral snake bite, asymptomatic 6 hr post-bite. Action?", back: "Long observation period — symptoms can be delayed up to 13 hr. Some experts give prophylactic antivenom. Antivenom less effective once neurologic symptoms develop. Admit for prolonged observation", tags: ["envtox"] },
  { id: "qc-64", domain: "env", front: "Black widow bite with severe abdominal pain mimicking surgical abdomen. Treatment?", back: "Opioids + benzodiazepines first-line. Calcium gluconate NOT effective per modern data. Antivenom reserved for severe refractory cases — significant anaphylaxis risk", tags: ["envtox"] },
  { id: "qc-65", domain: "env", front: "Severe frostbite 3 yo digits, presented 12 hr post-exposure. Treatment?", back: "Rewarm in 37-39°C bath until thawed. Cauchy grade after rewarming. If grade 3-4 with imaging confirming perfusion deficit, alteplase IV or IA per ABA. Iloprost alternative now available [Aurlumyn FDA 2024]. Anticoagulation 1-4 wk + ASA", tags: ["envtox"] },
  { id: "qc-66", domain: "env", front: "Climber at 4500m with severe headache + ataxia + confusion. Diagnosis + first action?", back: "HACE — IMMEDIATE descent is life-saving. Bridge with O2, dexamethasone 8 mg load → 4 mg q6h, Gamow bag if descent delayed", tags: ["envtox"] },
  { id: "qc-67", domain: "env", front: "Climber at 3500m with severe dyspnea, cough, SpO2 84% on room air. Diagnosis + treatment?", back: "HAPE — descend ASAP. O2, nifedipine 30 mg ER q12h. AVOID diuretics. Sildenafil/tadalafil alternatives", tags: ["envtox"] },
  { id: "qc-68", domain: "env", front: "AMS prevention dose acetazolamide?", back: "125 mg PO BID starting 24 hr before ascent, continue 2-3 days at altitude. Treatment dose: 250 mg BID. SE: paresthesias, polyuria, taste alterations", tags: ["envtox"] },
  { id: "qc-69", domain: "env", front: "College football player collapses on field, T 41°C, confused. Diagnosis + cooling?", back: "EXERTIONAL heatstroke — ICE WATER IMMERSION immediately, neck-deep × 10-20 min, target 38-39°C. Cool first, transport second. NO antipyretics, NO dantrolene", tags: ["envtox"] },
  { id: "qc-70", domain: "env", front: "Elderly nursing home patient, T 40.5°C, anhidrotic, AMS during heat wave. Cooling method?", back: "CLASSIC heatstroke in elderly — EVAPORATIVE cooling (mist + fans) preferred. Ice water immersion not tolerated hemodynamically. Same supportive care", tags: ["envtox"] },
  { id: "qc-71", domain: "env", front: "Hiker found in snow, core temp 26°C, no palpable pulse. Action?", back: "Severe hypothermia — check pulse for FULL MINUTE before CPR. Handle gently. Initiate CPR if confirmed arrest. Withhold drugs at < 30°C; double intervals 30-34°C. Aggressive rewarming with ECMO/CPB if available. \"Not dead until warm and dead\" unless K > 12", tags: ["envtox"] },
  { id: "qc-72", domain: "env", front: "Avalanche victim, buried 50 min, core temp 24°C, K 13. Action?", back: "Termination criteria met — K > 12 = irreversible cellular lysis. Buried > 35 min with obstructed airway also poor. Reasonable to terminate resuscitation", tags: ["envtox"] },
  { id: "qc-73", domain: "env", front: "Drowning victim asymptomatic, normal lung exam, SpO2 97% RA. Disposition?", back: "Observe 4-8 hr, if still asymptomatic discharge with return precautions. \"Delayed drowning\" beyond 8 hr is rare. NO antibiotics, NO steroids", tags: ["envtox"] },
  { id: "qc-74", domain: "env", front: "Brown recluse bite with central necrosis + intravascular hemolysis. Treatment?", back: "Largely SUPPORTIVE. Local wound care + tetanus. NO antivenom in US. Dapsone limited evidence + risks. Steroids + transfusion for systemic loxoscelism", tags: ["envtox"] },
  { id: "qc-75", domain: "env", front: "Scuba diver surfaces too quickly, sudden LOC + hemiparesis. Diagnosis + treatment?", back: "AGE from pulmonary barotrauma → cerebral embolism. 100% O2 supine + HBO ASAP. Call DAN. NOT Trendelenburg [old teaching, no benefit, increases ICP]", tags: ["envtox"] },
  { id: "qc-76", domain: "env", front: "Scuba diver with joint pain + skin marbling 30 min after surfacing. Diagnosis?", back: "Type I decompression sickness — \"bends.\" 100% O2 + HBO. Less urgent than Type II/AGE but still definitive", tags: ["envtox"] },
  { id: "qc-77", domain: "env", front: "Bark scorpion sting in 5 yo with roving eye movements + secretions + tachycardia. Treatment?", back: "Grade 3 — Anascorp F(ab')2 antivenom 3 vials IV, may repeat. Benzos adjunct for autonomic symptoms", tags: ["envtox"] },
  { id: "qc-78", domain: "trauma", front: "SCD patient previously on voxelotor for VOC prevention asks if they should restart it. Best response?", back: "Cannot — voxelotor was WITHDRAWN worldwide September 2024 due to safety concerns. Consider hydroxyurea optimization, L-glutamine, or gene therapy referral", tags: ["heme"] },
  { id: "qc-79", domain: "trauma", front: "SCD adult with new bilateral pulmonary infiltrates, fever, hypoxia. Diagnosis + key interventions?", back: "Acute chest syndrome → ceftriaxone + azithromycin, O2, incentive spirometry, simple or exchange transfusion based on severity. #1 mortality cause", tags: ["heme"] },
  { id: "qc-80", domain: "trauma", front: "Child with SCD on chronic transfusion develops ferritin 2200. Next step?", back: "Iron chelation — deferasirox oral first-line, or deferoxamine/deferiprone alternatives", tags: ["heme"] },
  { id: "qc-81", domain: "trauma", front: "Adult SCD patient with new hemiparesis. tPA or transfusion?", back: "EMERGENT EXCHANGE TRANSFUSION to HbS < 30%. tPA is NOT recommended in SCD stroke", tags: ["heme"] },
  { id: "qc-82", domain: "trauma", front: "Pediatric SCD patient with sudden Hb drop and rapidly enlarging spleen. Diagnosis?", back: "Splenic sequestration — emergent transfusion; can develop hypovolemic shock", tags: ["heme"] },
  { id: "qc-83", domain: "trauma", front: "Patient on UFH day 7, platelets dropped from 280 to 95, develops new DVT. Diagnosis + management?", back: "HIT — STOP heparin, start argatroban or bivalirudin. Confirm with PF4 ELISA + SRA. NO platelet transfusion. NO warfarin until plts recover", tags: ["heme"] },
  { id: "qc-84", domain: "trauma", front: "Patient on apixaban with ICH. Reversal agent?", back: "Andexanet alfa preferred; 4F-PCC if unavailable. Note black box for thrombosis", tags: ["heme"] },
  { id: "qc-85", domain: "trauma", front: "Patient on dabigatran with major GI bleed. Reversal?", back: "Idarucizumab 5 g IV ×1; alternative: hemodialysis since dabigatran is dialyzable", tags: ["heme"] },
  { id: "qc-86", domain: "trauma", front: "INR 12 on warfarin, minor bruising only. Management?", back: "Hold warfarin, give oral vitamin K 2.5–5 mg, recheck INR; no need for PCC/FFP without bleeding", tags: ["heme"] },
  { id: "qc-87", domain: "trauma", front: "VWD Type 2B patient with major bleed. Why is DDAVP contraindicated and what to use instead?", back: "DDAVP causes paradoxical thrombocytopenia in 2B by aggregating remaining VWF. Use VWF concentrate", tags: ["heme"] },
  { id: "qc-88", domain: "trauma", front: "70 kg severe hemophilia A patient with ICH. F8 dose?", back: "Target 100% → 70 × 100 × 0.5 = 3500 units IV bolus, then continuous infusion or q8–12h dosing", tags: ["heme"] },
  { id: "qc-89", domain: "trauma", front: "Hemophilia A patient on emicizumab develops a breakthrough bleed; pharmacist asked about adding aPCC. Concern?", back: "Emicizumab + aPCC = severe thrombotic microangiopathy; BLACK BOX. Use rFVIIa instead", tags: ["heme"] },
  { id: "qc-90", domain: "trauma", front: "Patient with microangiopathic hemolytic anemia, thrombocytopenia, normal PT/PTT, schistocytes, ADAMTS13 < 5%. Diagnosis + treatment?", back: "TTP — emergent plasma exchange. No platelet transfusion", tags: ["heme"] },
  { id: "qc-91", domain: "trauma", front: "Triple-positive antiphospholipid syndrome with VTE — DOAC or warfarin?", back: "Warfarin — TRAPS trial showed rivaroxaban inferior; DOACs contraindicated in triple-positive APS", tags: ["heme"] },
  { id: "qc-92", domain: "trauma", front: "Intermediate-high-risk PE at a PERT center — mechanical thrombectomy or CDT?", back: "PEERLESS 2024 favored LBMT over CDT — less deterioration, less ICU. Consider MT if available", tags: ["heme"] },
  { id: "qc-93", domain: "trauma", front: "Stable PE patient with RV strain on echo but normotensive. Systemic thrombolytics?", back: "NO — anticoagulation alone. Lytics only for hemodynamic instability or bailout if deterioration", tags: ["heme"] },
  { id: "qc-94", domain: "trauma", front: "Cancer-associated VTE — LMWH or DOAC?", back: "LMWH historically preferred; apixaban/edoxaban now acceptable per Caravaggio/Hokusai-Cancer. Avoid rivaroxaban in luminal GI cancer", tags: ["heme"] },
  { id: "qc-95", domain: "trauma", front: "Why no platelet transfusion in TTP unless life-threatening bleed?", back: "Adds substrate for ongoing microthrombus formation — worsens organ ischemia", tags: ["heme"] },
  { id: "qc-96", domain: "gi", front: "Treatment-naïve H. pylori patient in the US — preferred first-line regimen per 2024 ACG?", back: "Optimized bismuth quadruple therapy × 14 days. PPI-clarithro triple NO LONGER first-line", tags: ["gi"] },
  { id: "qc-97", domain: "gi", front: "Patient with APAP 25 g ingestion 5 hr ago. Next steps?", back: "Check 4-hr level, plot on Rumack-Matthew, start IV NAC 150 mg/kg load if at/above treatment line. Don't wait for AST elevation", tags: ["gi"] },
  { id: "qc-98", domain: "gi", front: "APAP ingestion 18 hr ago, AST 8000, INR 4, encephalopathy, Cr 4, pH 7.2. Apply King's College criteria?", back: "pH < 7.3 ALONE meets KCC for APAP-ALF → transplant evaluation", tags: ["gi"] },
  { id: "qc-99", domain: "gi", front: "Cirrhotic with refractory ascites + Cr rising from 1.0 to 2.5 over 5 days, no improvement after albumin challenge. Diagnosis + treatment?", back: "HRS-AKI → terlipressin + albumin, or norepi/midodrine+octreotide+albumin if terlipressin unavailable", tags: ["gi"] },
  { id: "qc-100", domain: "gi", front: "Cirrhotic with active variceal bleed + ascites — antibiotic ppx?", back: "Ceftriaxone 1 g IV daily × 7 days — prevents SBP and reduces mortality", tags: ["gi"] },
  { id: "qc-101", domain: "gi", front: "Patient with SBP and Cr 1.5, BUN 35 — does albumin help?", back: "YES — 1.5 g/kg day 1, 1 g/kg day 3. Strongest benefit in high-risk group: BUN > 30, Cr > 1, or bili > 4", tags: ["gi"] },
  { id: "qc-102", domain: "gi", front: "Acute pancreatitis patient — aggressive vs moderate fluid resuscitation?", back: "MODERATE per WATERFALL 2022 — LR 1.5 mL/kg/hr after 10 mL/kg bolus if hypovolemic. Aggressive harm", tags: ["gi"] },
  { id: "qc-103", domain: "gi", front: "Gallstone pancreatitis with cholangitis — ERCP timing?", back: "Urgent within 24–48 hr. Without cholangitis: ERCP routine NOT beneficial per APEC", tags: ["gi"] },
  { id: "qc-104", domain: "gi", front: "First recurrence of CDI — best treatment?", back: "Fidaxomicin standard or extended-pulsed regimen, OR vanco taper-pulse. Add bezlotoxumab if high recurrence risk", tags: ["gi"] },
  { id: "qc-105", domain: "gi", front: "Third CDI recurrence — options?", back: "FMT, OR Rebyota rectal enema, OR Vowst oral capsules — all reduce recurrence by ~30% post-standard-abx", tags: ["gi"] },
  { id: "qc-106", domain: "gi", front: "HCV patient with HBsAg+ starting glecaprevir/pibrentasvir — concern?", back: "HBV REACTIVATION — FDA black box. Treat or monitor HBV concurrently", tags: ["gi"] },
  { id: "qc-107", domain: "gi", front: "Patient on simvastatin 40 mg needs HCV treatment. Concern with G/P?", back: "CTN — avoid simvastatin/lovastatin with G/P; switch to pravastatin or rosuvastatin at low dose", tags: ["gi"] },
  { id: "qc-108", domain: "gi", front: "Patient with traveler's diarrhea from SE Asia. First-line abx?", back: "Azithromycin 1 g single dose — FQ resistance in Campylobacter; rifaximin only for noninvasive", tags: ["gi"] },
  { id: "qc-109", domain: "gi", front: "Suspected EHEC (E. coli O157:H7) diarrhea — antibiotic?", back: "NO — increases HUS risk via Shiga toxin release. Supportive only. AVOID loperamide too", tags: ["gi"] },
  { id: "qc-110", domain: "gi", front: "Cirrhotic with refractory variceal bleeding after EVL — next step?", back: "Balloon tamponade as bridge → emergent TIPS. Consider early TIPS in Child B with active bleeding or Child C 10–13", tags: ["gi"] },
  { id: "qc-111", domain: "gi", front: "Variceal bleeding prevention beta-blocker of choice?", back: "Carvedilol preferred per Baveno VII — better HVPG reduction. Nadolol/propranolol acceptable", tags: ["gi"] },
  { id: "qc-112", domain: "gi", front: "Cirrhotic GI bleed with INR 6 on warfarin. Reversal?", back: "10 mg IV vitamin K + 4F-PCC 25–50 u/kg. Vit K alone is too slow", tags: ["gi"] },
  { id: "qc-113", domain: "gi", front: "Patient post-liver transplant with CMV reactivation. Drug?", back: "Ganciclovir IV or valganciclovir PO; check viral load + biopsy if invasive disease suspected", tags: ["gi"] },
  { id: "qc-114", domain: "id", front: "Asplenic patient with dog bite presents with sepsis 24 hr later. Most likely organism?", back: "Capnocytophaga canimorsus — purpura fulminans, DIC. Cover with amp/sulbactam or pip-tazo + supportive care", tags: ["id"] },
  { id: "qc-115", domain: "id", front: "\"Fight bite\" (clenched-fist injury to mouth). Empiric coverage + closure approach?", back: "Amox-clav for Eikenella corrodens. Delayed closure or leave open. Always image — high risk of joint capsule/tendon penetration", tags: ["id"] },
  { id: "qc-116", domain: "id", front: "Patient with prior rabies pre-exposure vaccination receives a high-risk bite. PEP regimen?", back: "NO HRIG. 2 booster vaccine doses on days 0 and 3", tags: ["id"] },
  { id: "qc-117", domain: "id", front: "Unvaccinated patient bitten by bat. PEP regimen?", back: "HRIG 20 IU/kg [infiltrate around wound] + rabies vaccine on days 0, 3, 7, 14", tags: ["id"] },
  { id: "qc-118", domain: "id", front: "65-yo immunocompetent adult who had PPSV23 5 yr ago. Next pneumococcal vaccine?", back: "PCV20 OR PCV21 single dose — no further doses needed. ACIP also lowered age threshold to 50 in 2024", tags: ["id"] },
  { id: "qc-119", domain: "id", front: "Hospitalized influenza, day 4 of symptoms. Oseltamivir indicated?", back: "YES — start regardless of symptom duration in hospitalized patients", tags: ["id"] },
  { id: "qc-120", domain: "id", front: "COVID outpatient on simvastatin 40 mg. Paxlovid considerations?", back: "Hold simvastatin during 5 d Paxlovid + 2 d after; or switch to pravastatin/pitavastatin/rosuvastatin at lowest dose. Review ALL meds", tags: ["id"] },
  { id: "qc-121", domain: "id", front: "Severe CAP requiring ICU. Best empiric regimen?", back: "β-lactam [ceftriaxone or amp/sulbactam] + MACROLIDE > FQ in severe CAP per 2019 IDSA/ATS. Add MRSA/Pseudomonas coverage if risk factors", tags: ["id"] },
  { id: "qc-122", domain: "id", front: "LP delayed for CT in suspected bacterial meningitis. When to start abx?", back: "IMMEDIATELY after blood cultures — do not wait for CT or LP. Add dex 0.15 mg/kg q6h × 4 d BEFORE or WITH abx for suspected pneumococcal", tags: ["id"] },
  { id: "qc-123", domain: "id", front: "Suspected bacterial meningitis, age 65, HIV+. Empiric?", back: "Vancomycin + ceftriaxone + AMPICILLIN — Listeria coverage for > 50 yr or immunocompromised. Plus dexamethasone", tags: ["id"] },
  { id: "qc-124", domain: "id", front: "Active drug-susceptible pulmonary TB. Standard regimen?", back: "RIPE × 2 mo → INH/rifampin × 4 mo. Add B6 with INH. Monitor LFTs. Or new 4-mo rifapentine/moxifloxacin regimen for eligible patients", tags: ["id"] },
  { id: "qc-125", domain: "id", front: "Patient on rifampin for TB started on warfarin. Pharmacy concern?", back: "Rifampin is strong CYP3A4 INDUCER — drastically reduces warfarin level. Will need higher dose; or consider alternative anticoagulant; monitor INR closely", tags: ["id"] },
  { id: "qc-126", domain: "id", front: "MRSA bacteremia + endocarditis. Vancomycin trough vs AUC monitoring?", back: "AUC 400-600 per 2020 ASHP/IDSA — trough-only no longer standard", tags: ["id"] },
  { id: "qc-127", domain: "id", front: "Patient with PCN-anaphylaxis needs surgical prophylaxis. Cefazolin OK?", back: "Generally SAFE — different R1 side chain; <1% cross-reactivity. Document the rationale or skin-test first if uncertain", tags: ["id"] },
  { id: "qc-128", domain: "id", front: "Patient with ceftazidime anaphylaxis needs gram-neg coverage. Aztreonam?", back: "AVOID — shares side chain with ceftazidime. Use another class", tags: ["id"] },
  { id: "qc-129", domain: "id", front: "70 kg septic shock patient, NE at 0.3 mcg/kg/min × 5 hr, MAP 62. Next step?", back: "Add vasopressin 0.03 u/min; consider hydrocortisone 200 mg/day — meets criteria of NE ≥ 0.25 mcg/kg/min ≥ 4 hr", tags: ["id"] },
  { id: "qc-130", domain: "id", front: "ARDS patient with PaO2/FiO2 130. PEEP strategy?", back: "HIGHER PEEP > lower PEEP per SSC; consider proning > 12 hr/d. The original \"against PEEP titration\" note was reversed", tags: ["id"] },
  { id: "qc-131", domain: "id", front: "Sepsis patient on EN. When should TPN be added?", back: "NOT within 72 hr per EPaNIC — delay PN ≥ 7 d if EN tolerated", tags: ["id"] },
  { id: "qc-132", domain: "id", front: "HIV PEP regimen for pregnant patient?", back: "TDF/FTC + DOLUTEGRAVIR — current preferred. Older \"avoid DTG in pregnancy\" guidance is OUT OF DATE based on Tsepamo follow-up", tags: ["id"] },
  { id: "qc-133", domain: "id", front: "Empiric treatment for uncomplicated urogenital gonorrhea today?", back: "Ceftriaxone 500 mg IM MONOTHERAPY. Dual therapy with azithromycin is OUT per 2020 CDC update. Add doxy ONLY if chlamydia not ruled out", tags: ["id"] },
  { id: "qc-134", domain: "id", front: "Primary syphilis treatment?", back: "Benzathine PCN G 2.4 million units IM × 1. Late latent: same dose weekly × 3. Neuro: aqueous crystalline PCN G 18-24 million u/day IV × 10-14 d. Pregnant + PCN allergic: DESENSITIZE", tags: ["id"] },
  { id: "qc-135", domain: "id", front: "Patient develops fever, chills, hypotension 4 hr after first PCN dose for syphilis. Diagnosis + action?", back: "Jarisch-Herxheimer — not allergy. APAP + fluids; continue treatment", tags: ["id"] },
  { id: "qc-136", domain: "id", front: "Patient with PCN-anaphylaxis needs surgical prophylaxis. Cefazolin?", back: "Generally SAFE — different R1 side chain; <1% cross-reactivity. Document the discussion or skin-test first if uncertain", tags: ["id"] },
  { id: "qc-137", domain: "id", front: "Patient with ceftazidime anaphylaxis needs gram-neg coverage. Aztreonam?", back: "AVOID — shares side chain with ceftazidime. Use another class", tags: ["id"] },
  { id: "qc-138", domain: "id", front: "MRSA bacteremia + endocarditis. Vancomycin or daptomycin?", back: "Either; if vanco MIC > 1.5-2, switch to dapto 8-12 mg/kg. AUC 400-600 target for vanco. NOT linezolid for endovascular — bacteriostatic", tags: ["id"] },
  { id: "qc-139", domain: "id", front: "E. faecalis native valve endocarditis. Combination of choice?", back: "Ampicillin + ceftriaxone — replaces amp+gent in most cases per Fernández-Hidalgo 2013. Lower nephrotoxicity, equal efficacy", tags: ["id"] },
  { id: "qc-140", domain: "id", front: "CAP inpatient in ICU. Best empiric regimen?", back: "β-lactam [ceftriaxone or amp/sulbactam] + macrolide; FQ acceptable but macrolide preferred in severe per 2019 IDSA/ATS. Add MRSA/Pseudomonas coverage if risk factors", tags: ["id"] },
  { id: "qc-141", domain: "id", front: "LP delayed for CT in suspected bacterial meningitis. When start abx?", back: "IMMEDIATELY after blood cultures — do not wait for CT or LP. Add dex 0.15 mg/kg q6h × 4 d BEFORE or WITH abx for suspected pneumococcal", tags: ["id"] },
  { id: "qc-142", domain: "id", front: "Suspected bacterial meningitis age 65 with HIV. Empiric?", back: "Vancomycin + ceftriaxone + AMPICILLIN — Listeria coverage for > 50 yr or immunocompromised. Plus dexamethasone", tags: ["id"] },
  { id: "qc-143", domain: "id", front: "Hospitalized influenza, day 4 of symptoms. Oseltamivir?", back: "YES — START regardless of symptom duration in hospitalized patients", tags: ["id"] },
  { id: "qc-144", domain: "id", front: "COVID outpatient on simvastatin 40 mg. Paxlovid?", back: "Risk of rhabdo — hold simvastatin during 5 d Paxlovid + 2 d after; or switch to pravastatin/pitavastatin/rosuvastatin low dose. Review ALL meds for ritonavir interactions", tags: ["id"] },
  { id: "qc-145", domain: "id", front: "Active drug-susceptible pulmonary TB. Standard regimen?", back: "RIPE × 2 mo → INH/rifampin × 4 mo. Add B6 with INH. Monitor LFTs. Or new 4-mo regimen with rifapentine/moxi for eligible patients", tags: ["id"] },
  { id: "qc-146", domain: "id", front: "Patient on rifampin for TB started on warfarin. Concern?", back: "Rifampin is strong CYP3A4 INDUCER — drastically reduces warfarin level. Will need higher dose; or change regimen if possible", tags: ["id"] },
  { id: "qc-147", domain: "id", front: "Asplenic patient with dog bite presents with sepsis 24 hr later. Organism?", back: "Capnocytophaga canimorsus — purpura fulminans, DIC. Cover with amp/sulbactam or pip-tazo + supportive care", tags: ["id"] },
  { id: "qc-148", domain: "id", front: "Hand cellulitis after fist-fight (\"fight bite\"). Empiric?", back: "Amox-clav — covers Eikenella corrodens, ~30% of human bites. Consider washout in OR for joint involvement", tags: ["id"] },
  { id: "qc-149", domain: "id", front: "Diabetic foot infection, mod-severe, chronic ulcer. Empiric?", back: "Amp/sulbactam or pip-tazo + vancomycin for MRSA. Cover Pseudomonas if maceration/chronic. Surgical eval mandatory", tags: ["id"] },
  { id: "qc-150", domain: "id", front: "Necrotizing fasciitis treatment?", back: "EMERGENT surgical debridement + vancomycin + pip-tazo + CLINDAMYCIN [anti-toxin] + IVIG if strep TSS. LRINEC score ≥ 6 supports but clinical suspicion overrides", tags: ["id"] },
  { id: "qc-151", domain: "id", front: "65-yo immunocompetent adult who had PPSV23 5 yr ago. Next pneumococcal vaccine?", back: "PCV20 or PCV21 single dose — no further doses needed per updated ACIP", tags: ["id"] },
  { id: "qc-152", domain: "id", front: "Pregnancy + ASB on UA. Treat?", back: "YES — pregnancy is one of the two indications to treat ASB. Nitrofurantoin 100 mg BID × 7 d (avoid 3rd trimester) or cephalexin or amoxicillin", tags: ["id"] },
  { id: "qc-153", domain: "neuro", front: "Status epilepticus 7 minutes in, no IV access. Best initial BZD?", back: "IM midazolam 10 mg — RAMPART trial; equivalent to IV lorazepam 4 mg. Underdosing is the most common mistake", tags: ["neuro"] },
  { id: "qc-154", domain: "neuro", front: "Phenobarbital 15-yo INH overdose with seizures — best initial therapy?", back: "Pyridoxine [B6] 5 g IV or 1 g per gram INH ingested. Benzos in addition. Phenytoin is contraindicated in INH-induced seizures", tags: ["neuro"] },
  { id: "qc-155", domain: "neuro", front: "MG patient in respiratory distress, FVC 12 mL/kg. Next step?", back: "Intubate. Concurrent PLEX or IVIG + high-dose steroid. NMBA for intubation: nondepolarizing rocuronium at 50–66% standard dose; avoid succinylcholine — unpredictable", tags: ["neuro"] },
  { id: "qc-156", domain: "neuro", front: "Ocular MG outpatient — first-line drug?", back: "Pyridostigmine [Mestinon] 30–60 mg PO q4–6h — NOT physostigmine. Physostigmine is for anticholinergic toxicity", tags: ["neuro"] },
  { id: "qc-157", domain: "neuro", front: "AIS within 4.5 hr, NIHSS 4 with dominant-hand weakness preventing patient’s job. Lytic?", back: "YES per 2026 update — “disabling deficits” criterion overrides the older “NIHSS 0–5 exclusion.”", tags: ["neuro"] },
  { id: "qc-158", domain: "neuro", front: "AIS patient on apixaban took last dose 30 hr ago. Lytic?", back: "Generally NO unless calibrated anti-Xa < 0.5 IU/mL. Andexanet before tPA is NOT recommended", tags: ["neuro"] },
  { id: "qc-159", domain: "neuro", front: "AIS on dabigatran, last dose 18 hr ago, NIHSS 14. Reversal before tPA?", back: "Idarucizumab 5 g IV [Class 2b] is reasonable, then proceed with tPA", tags: ["neuro"] },
  { id: "qc-160", domain: "neuro", front: "Anterior LVO presenting at 10 hr post-symptom-onset, NIHSS 12. EVT candidate?", back: "YES — per 2026 update, EVT now Class 1 for anterior LVO up to 24 hr with favorable imaging [SELECT2, ANGEL-ASPECT]", tags: ["neuro"] },
  { id: "qc-161", domain: "neuro", front: "Stanford A vs Stanford B aortic dissection. Management?", back: "A = surgical emergency [ascending aorta]; B = medical first with esmolol/labetalol → SBP < 120, HR < 60. Endovascular if complicated B", tags: ["neuro"] },
  { id: "qc-162", domain: "neuro", front: "aSAH day 7, new left-sided weakness, TCD shows elevated velocities. Treatment?", back: "INDUCED HYPERTENSION + euvolemia. Don’t do hemodilution/hypervolemia — outdated triple-H", tags: ["neuro"] },
  { id: "qc-163", domain: "neuro", front: "ICH on warfarin, INR 4.8. Reversal?", back: "4F-PCC 35 u/kg + vitamin K 10 mg IV. NOT FFP first — too slow, volume overload risk", tags: ["neuro"] },
  { id: "qc-164", domain: "neuro", front: "ICH on apixaban, last dose 6 hr ago, life-threatening bleed. Reversal?", back: "Andexanet alfa high-dose IV bolus + infusion; if unavailable → 4F-PCC 50 u/kg", tags: ["neuro"] },
  { id: "qc-165", domain: "neuro", front: "ICH on aspirin alone, planned neurosurgery. Platelet transfusion?", back: "Only if proceeding to neurosurgery [aim plt > 100K] OR plt < 100K already. PATCH trial showed harm with routine platelet transfusion in spontaneous ICH on antiplatelets", tags: ["neuro"] },
  { id: "qc-166", domain: "neuro", front: "Migraine in pregnant patient. Avoid which?", back: "Triptans cautiously [data limited but not contraindicated]; AVOID valproic acid [teratogenic], DHE, ergots. Safer: APAP, metoclopramide, prochlorperazine, magnesium, occipital nerve block", tags: ["neuro"] },
  { id: "qc-167", domain: "neuro", front: "tPA-related orolingual angioedema unresponsive to steroid + antihistamine. Next?", back: "Epi 0.3 mL SQ; then icatibant or C1-INH for bradykinin pathway — the likely mechanism", tags: ["neuro"] },
  { id: "qc-168", domain: "neuro", front: "Eclamptic seizure. First-line?", back: "Magnesium sulfate 4–6 g IV load, then 1–2 g/hr infusion. Hydralazine or labetalol for BP. Delivery is definitive", tags: ["neuro"] },
  { id: "qc-169", domain: "neuro", front: "Post-transplant patient on tacrolimus develops headache + seizure + cortical blindness; MRI shows posterior edema. Diagnosis?", back: "PRES — stop tacrolimus, control BP. Reversible if caught early", tags: ["neuro"] },
  { id: "qc-170", domain: "neuro", front: "TIA, ABCD2 = 5. Disposition + antiplatelet plan?", back: "High-risk — admit or rapid TIA clinic eval; start DAPT [aspirin + clopidogrel or aspirin + ticagrelor] x 21 days then monotherapy per CHANCE/POINT/THALES", tags: ["neuro"] },
  { id: "qc-171", domain: "special", front: "Pregnant patient at 28 wks with severe pre-eclampsia, BP 175/115. First-line BP treatment options?", back: "Per ACOG Table 2 [your image]: labetalol IV, hydralazine IV, OR nifedipine IR PO. All three acceptable", tags: ["ob"] },
  { id: "qc-172", domain: "special", front: "Patient on mag infusion for severe pre-eclampsia, RR drops to 8 and DTRs are absent. Action?", back: "STOP mag immediately, give CALCIUM GLUCONATE 1 g IV [10 mL of 10%] over 3–5 min, support airway. Don’t use calcium chloride peripherally", tags: ["ob"] },
  { id: "qc-173", domain: "special", front: "Patient at 32 wks gestation in preterm labor. Tocolytic of choice?", back: "Nifedipine PO first-line; indomethacin acceptable < 32 wks. Avoid mag for tocolysis. Give betamethasone for fetal lung maturity AND mag for neuroprotection", tags: ["ob"] },
  { id: "qc-174", domain: "special", front: "Why mag sulfate for neuroprotection in preterm labor?", back: "Reduces cerebral palsy risk per BEAM trial. Give at < 32 wks if delivery anticipated within 24 hr. 4 g load + 1 g/hr infusion", tags: ["ob"] },
  { id: "qc-175", domain: "special", front: "Postpartum hemorrhage patient with severe asthma. Uterotonic to AVOID?", back: "Carboprost [Hemabate] — PGF2α causes bronchospasm. Use methylergonovine if no HTN, OR misoprostol", tags: ["ob"] },
  { id: "qc-176", domain: "special", front: "Postpartum hemorrhage in patient with severe pre-eclampsia. Uterotonic to AVOID?", back: "Methylergonovine — potent vasoconstrictor, can precipitate hypertensive crisis. Use carboprost if no asthma, OR misoprostol", tags: ["ob"] },
  { id: "qc-177", domain: "special", front: "TXA in PPH — timing?", back: "Within 3 hours of birth per WOMAN trial. 1 g IV over 10 min, may repeat after 30 min. Efficacy drops sharply > 3 hr", tags: ["ob"] },
  { id: "qc-178", domain: "special", front: "Pregnant code at 28 wks, no ROSC at 4 minutes. Next step?", back: "Perimortem C-section AT BEDSIDE — don’t transport. Improves maternal AND fetal outcomes via aortocaval decompression. Indication: ≥ 20 wks / fundus at umbilicus", tags: ["ob"] },
  { id: "qc-179", domain: "special", front: "Hyperemesis gravidarum patient receiving D5W. Order of administration?", back: "Thiamine 100 mg IV FIRST, then dextrose. Dextrose before thiamine in thiamine-deficient patient can precipitate Wernicke encephalopathy", tags: ["ob"] },
  { id: "qc-180", domain: "special", front: "LAST (local anesthetic toxicity) in OB. Treatment?", back: "20% lipid emulsion 1.5 mL/kg IV bolus over 1 min, then 0.25 mL/kg/min infusion. Repeat bolus q3–5 min for persistent CV collapse. Max 12 mL/kg", tags: ["ob"] },
  { id: "qc-181", domain: "special", front: "Patient with ectopic, getting MTX. NSAID for pain control — OK?", back: "NO — NSAIDs reduce MTX renal clearance, increasing toxicity. Use APAP or opioid for ectopic pain control while on MTX", tags: ["ob"] },
  { id: "qc-182", domain: "special", front: "Rh-negative mom at 28 weeks. Routine RhoGAM dose?", back: "300 mcg [1500 IU] IM at 28 wks AND within 72 hr postpartum if newborn Rh+. Also after any sensitizing event — miscarriage, ectopic, amnio, trauma", tags: ["ob"] },
  { id: "qc-183", domain: "special", front: "Chorioamnionitis at term. Antibiotics?", back: "Ampicillin 2 g IV q6h + gentamicin 1.5 mg/kg q8h. Add clindamycin or metronidazole if cesarean. Continue until afebrile 24–48 hr postpartum", tags: ["ob"] },
  { id: "qc-184", domain: "special", front: "Postpartum patient day 3 with dyspnea, EF 30% on echo, no other cardiac history. Diagnosis + key management?", back: "Peripartum cardiomyopathy. Heart failure regimen + consider bromocriptine 2.5 mg BID. Anticoagulate if EF < 35%. Counsel re: high recurrence risk in future pregnancy", tags: ["ob"] },
  { id: "qc-185", domain: "special", front: "PE in pregnancy, hemodynamically stable. Anticoagulant?", back: "LMWH — enoxaparin 1 mg/kg SQ q12h. Avoid DOACs and warfarin first trimester. Switch to UFH near term for neuraxial anesthesia", tags: ["ob"] },
  { id: "qc-186", domain: "special", front: "Pregnant patient with new mild chronic HTN per CHAP trial. Treatment threshold?", back: "Per 2022 CHAP/ACOG: treat to target < 140/90. Updated lower threshold vs older “treat only severe HTN” teaching", tags: ["ob"] },
  { id: "qc-187", domain: "onc", front: "Patient newly diagnosed with Burkitt lymphoma about to start chemo, K 5.8, uric acid 12, no urine output for 4 hr. Diagnosis + key treatments?", back: "TLS — aggressive IV NS + rasburicase 0.2 mg/kg [or fixed 3–7.5 mg]; allopurinol too slow alone. Check G6PD before rasburicase", tags: ["onc"] },
  { id: "qc-188", domain: "onc", front: "TLS patient has K 7.2 with peaked T waves. Calcium gluconate — over how long?", back: "2–5 minutes, NOT 30 min. 30 min is for chronic hypocalcemia repletion; 2–5 min for acute membrane stabilization", tags: ["onc"] },
  { id: "qc-189", domain: "onc", front: "Why must uric acid sample after rasburicase be on ice?", back: "Rasburicase continues to break down uric acid ex vivo → falsely low results. Transport on ice, analyze within 4 hr", tags: ["onc"] },
  { id: "qc-190", domain: "onc", front: "Patient on azathioprine for IBD develops gout, started on allopurinol. Concern?", back: "Severe myelosuppression — allopurinol blocks xanthine oxidase metabolism of azathioprine → toxic accumulation. Either avoid combo or reduce aza dose to 25–33%", tags: ["onc"] },
  { id: "qc-191", domain: "onc", front: "HCM patient with Ca 14, creatinine 4.0. Bisphosphonate of choice?", back: "Denosumab — not renally cleared, safe in CKD. Zoledronic acid would need to be held. Watch for rebound hypoCa after stopping denosumab", tags: ["onc"] },
  { id: "qc-192", domain: "onc", front: "HCM patient with Ca 15.5 needs rapid lowering. Bisphosphonate takes 48–72h. What’s the bridge?", back: "Calcitonin 4 IU/kg SC/IM q12h — fastest [2–6 hr onset]; bridges 24–48 hr while waiting for bisphosphonate/denosumab. Tachyphylaxis within 48–72 hr", tags: ["onc"] },
  { id: "qc-193", domain: "onc", front: "FN patient time to abx?", back: "Within 1 HOUR of presentation per IDSA/NCCN — same as sepsis. Empiric anti-pseudomonal beta-lactam", tags: ["onc"] },
  { id: "qc-194", domain: "onc", front: "FN patient with cefepime monotherapy, develops new infiltrate on CT, MRSA risk factors. Add what?", back: "Vancomycin — first-line empiric gram+ coverage. AUC 400–600", tags: ["onc"] },
  { id: "qc-195", domain: "onc", front: "FN patient on FQ prophylaxis develops fever. What to do?", back: "DO NOT use FQ for treatment — select for resistance. Use anti-pseudomonal beta-lactam", tags: ["onc"] },
  { id: "qc-196", domain: "onc", front: "Cancer patient with gastric cancer + new PE. DOAC choice?", back: "APIXABAN — lowest bleeding risk in mucosal cancers per Caravaggio. Avoid rivaroxaban + edoxaban [Hokusai-Cancer + SELECT-D showed higher mucosal bleeding]", tags: ["onc"] },
  { id: "qc-197", domain: "onc", front: "Cancer-VTE patient with platelets 30. Anticoagulation plan?", back: "Per ASH 2023: half-dose AC + transfuse platelets to > 25–50; full-dose if plt > 50. Hold if plt < 25", tags: ["onc"] },
  { id: "qc-198", domain: "onc", front: "New facial swelling, distended neck veins, dyspnea in lung cancer patient. Diagnosis + first steps?", back: "SVC syndrome — elevate HOB, avoid upper extremity IV. Endovascular stent fastest; biopsy needed BEFORE steroids if new presentation", tags: ["onc"] },
  { id: "qc-199", domain: "onc", front: "Cancer patient with new severe back pain at night. Next step?", back: "URGENT MRI of WHOLE spine to rule out malignant spinal cord compression. Start dex 10 mg IV bolus then 4 mg q6h while imaging. Don’t wait for neuro deficits", tags: ["onc"] },
  { id: "qc-200", domain: "onc", front: "Doxorubicin extravasation. Antidote?", back: "Dexrazoxane 1000 mg/m² IV in DIFFERENT limb within 6 hr, then day 2 + 500 mg/m² day 3. NO cold compress with dexrazoxane. Alternative: topical DMSO + cold compresses [no dexrazoxane]", tags: ["onc"] },
  { id: "qc-201", domain: "onc", front: "Vincristine extravasation. Antidote?", back: "Hyaluronidase 150–300 units SC around site + WARM compress. NEVER cold for vincas", tags: ["onc"] },
  { id: "qc-202", domain: "onc", front: "CAR-T day 3 post-infusion, fever 39, BP 78/50 responding to fluids, O2 4 L NC. Grading + treatment?", back: "Grade 2 CRS — tocilizumab 8 mg/kg IV [max 800 mg] first-line per ASTCT. Add dex if persistent or grade ≥ 3", tags: ["onc"] },
  { id: "qc-203", domain: "onc", front: "CAR-T patient with new confusion, can’t name objects, dysgraphia. Treatment?", back: "ICANS — dexamethasone 10 mg IV q6h [crosses BBB]. Tocilizumab does NOT cross BBB — ineffective for ICANS. Anakinra for refractory", tags: ["onc"] },
  { id: "qc-204", domain: "onc", front: "ICI patient on combo ipi+nivo develops new troponin elevation + chest pain + EF drop. Diagnosis + treatment?", back: "ICI myocarditis — high mortality. PERMANENT discontinuation + high-dose methylpred 1 g/day × 3–5 d. Add mycophenolate or infliximab if refractory", tags: ["onc"] },
  { id: "qc-205", domain: "onc", front: "Patient on cisplatin AC chemo. CINV ppx?", back: "4-drug HEC regimen: 5HT3 + NK1 + dex + olanzapine × 4 days", tags: ["onc"] },
  { id: "qc-206", domain: "special", front: "Well-appearing febrile infant 14 days old, T 38.5. Workup?", back: "Per AAP 2021: ALL infants 8-21 days need urine + blood + CSF + admit + empiric abx. No wiggle room", tags: ["peds"] },
  { id: "qc-207", domain: "special", front: "Well-appearing febrile infant 35 days old, T 38.3. Procalcitonin 0.3. Workup?", back: "Per AAP 2021: PNA 29-60 days with normal inflammatory markers — CSF NOT required, admit OR discharge with close follow-up", tags: ["peds"] },
  { id: "qc-208", domain: "special", front: "Neonate 5 days old with empiric sepsis. Antibiotic regimen?", back: "Ampicillin 100 mg/kg q8h + gentamicin 4-5 mg/kg q24h. Covers GBS, Listeria, E. coli. Ceftriaxone CONTRAINDICATED in neonates < 41 wk PMA due to bilirubin displacement/kernicterus risk + Ca incompatibility", tags: ["peds"] },
  { id: "qc-209", domain: "special", front: "Septic child in PICU with cold extremities, cap refill 4 sec. Vasopressor?", back: "Epinephrine — cold/decompensated shock, low CO, vasoconstricted. Cold shock more common in PEDIATRIC sepsis vs adults", tags: ["peds"] },
  { id: "qc-210", domain: "special", front: "Septic child with warm extremities, bounding pulses, hypotension. Vasopressor?", back: "Norepinephrine — warm/distributive shock, more adult-like presentation", tags: ["peds"] },
  { id: "qc-211", domain: "special", front: "Suspected pneumococcal meningitis in 30 yo. Steroid?", back: "DEX 10 mg IV 10-20 min BEFORE or WITH first abx — for ALL adults with suspected pneumococcal meningitis [Dutch trial mortality benefit]", tags: ["peds"] },
  { id: "qc-212", domain: "special", front: "Pediatric meningitis empiric for 3 yo?", back: "Ceftriaxone 50 mg/kg q12h + vancomycin 15 mg/kg q6h. Vanco added for ceftriaxone-resistant pneumococcus. NOT ampicillin — Listeria only in neonates or > 50 yr", tags: ["peds"] },
  { id: "qc-213", domain: "special", front: "Meningitis in 6-day-old admitted from home. Empiric?", back: "Ampicillin 75-100 mg/kg q6-8h + gentamicin 4-5 mg/kg q24h. Replace gent with ceftazidime if CSF analysis suggests infection. Add acyclovir if HSV risk factors", tags: ["peds"] },
  { id: "qc-214", domain: "special", front: "CSF shunt-related meningitis. Empiric + addition?", back: "Cefepime + vancomycin. ADD RIFAMPIN if staph + can't remove shunt — biofilm penetration", tags: ["peds"] },
  { id: "qc-215", domain: "special", front: "Croup, child has stridor at rest. Treatment?", back: "Dexamethasone 0.6 mg/kg (max 16 mg) PO/IV/IM + nebulized racepinephrine/L-epi. Observe 2-4 hr for rebound", tags: ["peds"] },
  { id: "qc-216", domain: "special", front: "RSV bronchiolitis in 4 mo old, no other comorbidities. Pharmacotherapy?", back: "NONE — supportive only. AAP recommends AGAINST albuterol, steroids, epi, antibiotics, chest PT. This is different from croup", tags: ["peds"] },
  { id: "qc-217", domain: "special", front: "First-line for neonatal status epilepticus?", back: "Phenobarbital 15-20 mg/kg load — confirmed by NEOLEV2 trial. Different from older kids/adults where levetiracetam or fosphenytoin preferred", tags: ["peds"] },
  { id: "qc-218", domain: "special", front: "Mild AOM in 4 yo, unilateral, no severe features. Antibiotic?", back: "Watch-and-wait acceptable for ≥ 2 yr unilateral non-severe AOM. If treating: amox 80-90 mg/kg/day × 5-7 d. Add clavulanate if amox in last 30 days or concurrent conjunctivitis", tags: ["peds"] },
  { id: "qc-219", domain: "special", front: "Severe pertussis in 6 mo old. Treatment?", back: "Azithromycin 10 mg/kg day 1, then 5 mg/kg days 2-5. Bactrim alternative. Doxycycline acceptable for severe pertussis in young children per CDC 2018 — old absolute age 8 rule no longer applies for short courses", tags: ["peds"] },
  { id: "qc-220", domain: "special", front: "Newborn whose mother had no GBS testing. Intrapartum ppx?", back: "PCN G 5 million u IV load → 2.5-3 million u q4h. Cefazolin if non-anaphylactic PCN allergy. Vancomycin if severe PCN allergy. Must be ≥ 4 hr before delivery", tags: ["peds"] },
  { id: "qc-221", domain: "special", front: "RSV ppx for premature 28-week infant entering RSV season?", back: "NIRSEVIMAB single IM dose now preferred over palivizumab monthly per AAP 2023", tags: ["peds"] },
  { id: "qc-222", domain: "psych", front: "Chronic opioid user with respiratory rate 6, found unresponsive. Naloxone dose?", back: "0.04-0.4 mg IV titrated to respiratory drive — start LOW to avoid precipitated withdrawal. Higher doses [2 mg] if opioid-naive or unknown", tags: ["psych"] },
  { id: "qc-223", domain: "psych", front: "Patient on chronic methadone for OUD develops fentanyl overdose. Naloxone strategy?", back: "Initial low dose 0.04-0.1 mg + may need INFUSION at 70% of effective bolus dose/hr — long-acting opioid requires sustained reversal", tags: ["psych"] },
  { id: "qc-224", domain: "psych", front: "Initiating buprenorphine for OUD — when to start?", back: "Wait for COWS ≥ 8-12, not just by time. Last short-acting opioid ~ 12-24 hr; methadone 48-72+ hr. Premature induction → precipitated withdrawal", tags: ["psych"] },
  { id: "qc-225", domain: "psych", front: "Buprenorphine micro-dosing indication?", back: "Bernese method — for patients on chronic high-dose opioids or methadone who can't safely undergo full withdrawal first", tags: ["psych"] },
  { id: "qc-226", domain: "psych", front: "Severe agitation, unknown cause. First-line?", back: "Lorazepam — your table. Single agent, broad coverage", tags: ["psych"] },
  { id: "qc-227", domain: "psych", front: "Severe agitation, known schizophrenia patient off meds. Choice?", back: "PO/IM olanzapine or ziprasidone, IV haldol. AVOID ketamine in psychiatric history", tags: ["psych"] },
  { id: "qc-228", domain: "psych", front: "Cocaine-induced chest pain + agitation. Pharm sequence?", back: "Benzodiazepines FIRST [lorazepam] — calms agitation + reduces sympathetic surge. Then nitrates for vasospasm. Phentolamine if refractory. AVOID pure beta-blockers — unopposed alpha-1 worsens vasoconstriction", tags: ["psych"] },
  { id: "qc-229", domain: "psych", front: "Patient on linezolid + tramadol develops hyperthermia, ankle clonus, agitation. Diagnosis + treatment?", back: "Serotonin syndrome — STOP serotonergic agents, supportive, cyproheptadine 12 mg load → 2 mg q2h. Benzos for agitation", tags: ["psych"] },
  { id: "qc-230", domain: "psych", front: "Patient on haldol days, lead-pipe rigidity, CK 12,000, T 40°C. Diagnosis + treatment?", back: "NMS — STOP antipsychotic, supportive cooling/IVF, dantrolene + bromocriptine", tags: ["psych"] },
  { id: "qc-231", domain: "psych", front: "TCA overdose, QRS 140 ms. Treatment?", back: "Sodium bicarbonate 1-2 mEq/kg IV bolus → infusion. Goal QRS < 100 ms, serum pH 7.45-7.55. Lipid emulsion for refractory hypotension. AVOID procainamide, physostigmine", tags: ["psych"] },
  { id: "qc-232", domain: "psych", front: "TCA overdose with seizures. AED choice?", back: "Benzodiazepines. AVOID phenytoin — worsens Na channel blockade", tags: ["psych"] },
  { id: "qc-233", domain: "psych", front: "Lithium level 4.2 in patient on chronic Li for bipolar, taking lisinopril recently for HTN. Action?", back: "Hemodialysis — Li > 4 is HD indication regardless of symptoms. ACE-i reduced Li clearance", tags: ["psych"] },
  { id: "qc-234", domain: "psych", front: "Bipolar patient post-lithium overdose, post-HD, level drops to 1.8. Disposition?", back: "Watch for REBOUND — Li redistributes from tissues back to plasma; level may rise. Repeat level in 4-6 hr; may need repeat HD", tags: ["psych"] },
  { id: "qc-235", domain: "psych", front: "Chronic alcoholic with new seizure during withdrawal. AED choice?", back: "LORAZEPAM 2-4 mg IV. NOT phenytoin — doesn't work for alcohol withdrawal seizures. Check Mg, replete", tags: ["psych"] },
  { id: "qc-236", domain: "psych", front: "Alcoholic with anticholinergic toxidrome (dry, red, hot, dilated pupils, AMS). Treatment?", back: "Benzos first. Physostigmine 0.5-2 mg IV if pure anticholinergic — but ONLY if ECG shows no signs of Na channel blockade [normal QRS, no terminal R wave aVR]. Avoid in TCA tox", tags: ["psych"] },
  { id: "qc-237", domain: "psych", front: "VPA overdose, level 1200, encephalopathy, ammonia 200. Treatment?", back: "HEMODIALYSIS [level > 850-1000, severe acidosis, encephalopathy] + L-carnitine 100 mg/kg IV load. NOT naloxone as primary therapy", tags: ["psych"] },
  { id: "qc-238", domain: "psych", front: "Anorexic patient with low Mg, on hospital diet starting. Concern?", back: "Refeeding syndrome — hypoPhos, hypoK, hypoMg, B1 deficiency. Give thiamine BEFORE feeds, replete electrolytes, advance feeds slowly", tags: ["psych"] },
  { id: "qc-239", domain: "psych", front: "Alcohol use disorder admitted, AMS, ataxia, ophthalmoplegia. Treatment?", back: "Active Wernicke's — HIGH-DOSE thiamine 500 mg IV TID × 2-3 days [not 100 mg]. Give BEFORE dextrose", tags: ["psych"] },
  { id: "qc-240", domain: "psych", front: "Cannabinoid hyperemesis. Pharm + non-pharm?", back: "Topical capsaicin 0.025-0.075% cream to abdomen + droperidol or haloperidol IV. AVOID opioids, benzos [worsen + don't help]. Definitive: cannabis cessation", tags: ["psych"] },
  { id: "qc-241", domain: "resp", front: "Severe asthma exacerbation, no response to nebs + steroids. Adjuncts?", back: "IV mag sulfate 2 g over 20 min; consider heliox; IV ketamine if intubating; epinephrine IM 0.3-0.5 mg", tags: ["pulm"] },
  { id: "qc-242", domain: "resp", front: "AECOPD with PaCO2 65, pH 7.28. First-line ventilation strategy?", back: "NIV/BiPAP — class 1A. Reduces intubation + mortality. Target gradual CO2 reduction, target pH > 7.30", tags: ["pulm"] },
  { id: "qc-243", domain: "resp", front: "Why target O2 88-92% (not higher) in AECOPD?", back: "Hyperoxia → reduced hypoxic vasoconstriction + Haldane effect → CO2 retention + acidosis. BTS trial showed doubled mortality with liberal O2", tags: ["pulm"] },
  { id: "qc-244", domain: "resp", front: "Patient on selexipag for PAH, hospitalized. Verify dose?", back: "Should be MICROGRAMS — 200-1600 mcg BID. \"200 mg\" is a 1000-fold overdose. Common medication error", tags: ["pulm"] },
  { id: "qc-245", domain: "resp", front: "PAH patient on epoprostenol IV via central line, pump alarms. Action?", back: "URGENT — replace pump immediately, NEVER abruptly stop. Abrupt cessation → rebound PAH crisis, death. Always have backup supplies", tags: ["pulm"] },
  { id: "qc-246", domain: "resp", front: "Severe ARDS patient on cisatracurium drip. RASS target?", back: "-4 to -5 — deep sedation REQUIRED when paralyzed. Add fentanyl/midazolam to ensure no awareness during NMB", tags: ["pulm"] },
  { id: "qc-247", domain: "resp", front: "Severe ARDS PaO2/FiO2 = 70 despite optimal vent. Next step?", back: "Prone positioning per PROSEVA — 16+ hr/day. If still refractory → VV-ECMO referral per EOLIA", tags: ["pulm"] },
  { id: "qc-248", domain: "resp", front: "Patient on ACE-inhibitor presents with tongue swelling. Mechanism + treatment?", back: "Bradykinin-mediated angioedema. Stop ACEi, airway management. Epi/antihistamines/steroids generally ineffective. Icatibant or C1-INH variable evidence. Lifelong ACEi avoidance", tags: ["pulm"] },
  { id: "qc-249", domain: "resp", front: "Anaphylaxis patient on metoprolol, BP 70/40 not responding to 3 epi doses + fluids. Next?", back: "GLUCAGON 1-5 mg IV — bypasses β blockade via direct cAMP. Then NE/vasopressin infusion. Methylene blue for catastrophic vasoplegia", tags: ["pulm"] },
  { id: "qc-250", domain: "resp", front: "Why moved away from routine antihistamines/steroids in anaphylaxis?", back: "No evidence they prevent biphasic reactions or improve mortality. Per 2023 Joint Task Force — selective use only, symptom relief", tags: ["pulm"] },
  { id: "qc-251", domain: "resp", front: "Trauma patient SBP 80, JVD, tracheal deviation, absent breath sounds left. Action?", back: "Tension pneumothorax — immediate needle decompression [2nd ICS MCL or 5th ICS AAL], then chest tube. Don't wait for CXR", tags: ["pulm"] },
  { id: "qc-252", domain: "resp", front: "Patient coughs up 600 mL blood in 1 hour. Initial positioning + treatment?", back: "BLEEDING-SIDE-DOWN lateral decubitus + early intubation with large-bore ETT. IR for bronchial artery embolization. TXA 1 g IV. Reverse any anticoagulation", tags: ["pulm"] },
  { id: "qc-253", domain: "resp", front: "CF patient with pseudomonas pulmonary exacerbation. Empiric abx?", back: "Dual antipseudomonal: β-lactam [cefepime/ceftaz/pip-tazo/mero] + tobramycin or FQ. 14-day course minimum. Higher weight-based doses due to CF altered PK", tags: ["pulm"] },
  { id: "qc-254", domain: "resp", front: "Patient with HLA-B*15:02 carbamazepine-induced TEN. Cross-reactive drugs to avoid?", back: "Lamotrigine, oxcarbazepine, phenytoin — share aromatic structure. Use valproate or levetiracetam alternatives", tags: ["pulm"] },
  { id: "qc-255", domain: "resp", front: "Patient with anaphylaxis fully responds to single epi dose, no asthma, reliable follow-up. Observation period?", back: "1 hour per 2023 update — NOT routine 4-6 hr anymore. Longer only if severe/refractory, asthma, biphasic risk factors", tags: ["pulm"] },
  { id: "qc-256", domain: "resp", front: "Asthma exacerbation post-intubation, sudden hypotension + difficult ventilation. Diagnosis?", back: "TENSION PNEUMOTHORAX from barotrauma — common complication. Immediate needle decompression, decrease tidal volumes, lengthen expiratory time", tags: ["pulm"] },
  { id: "qc-257", domain: "renal", front: "HypoNa 110 with seizure. Treatment?", back: "3% NaCl 100-150 mL bolus over 10-20 min, repeat up to 3× if seizures persist. Goal: raise Na 4-6 mEq/L to stop neuro symptoms. AVOID overshooting > 8-10 mEq/24h", tags: ["renal"] },
  { id: "qc-258", domain: "renal", front: "Patient overcorrected hypoNa, now Na rising 12 mEq in 8 hours. Action?", back: "\"Re-lower\" with D5W or 0.45% NaCl + DDAVP 1-2 mcg q6-8h to prevent further rise. ODS risk especially in alcoholic, hypoK, malnourished", tags: ["renal"] },
  { id: "qc-259", domain: "renal", front: "Patient with glucose 800 and measured Na 125. Corrected Na?", back: "Use 1.6 × (glucose-100)/100 correction: 125 + 1.6 × (800-100)/100 = 125 + 11.2 = ~136. Pseudohyponatremia from hyperglycemia", tags: ["renal"] },
  { id: "qc-260", domain: "renal", front: "Lithium-induced nephrogenic DI. Treatment?", back: "Thiazide + AMILORIDE (K-sparing, blocks ENaC where lithium accumulates) + Na restriction. Don't use desmopressin alone — kidneys won't respond", tags: ["renal"] },
  { id: "qc-261", domain: "renal", front: "Severe hyperK 6.8 with peaked T-waves on EKG. Initial actions in order?", back: "1. Calcium gluconate 1-3 g IV over 2-5 min for membrane stabilization. 2. Insulin 10 units + D50 25g IV for K shift. 3. Albuterol 10-20 mg neb for additional shift. 4. K binders (SZC or patiromer) or HD for removal", tags: ["renal"] },
  { id: "qc-262", domain: "renal", front: "HypoCa post-thyroid surgery + Mg 1.0. Why isn't IV Ca correcting it?", back: "Hypomagnesemia — Mg needed for PTH release + action. Replete Mg first/concurrently", tags: ["renal"] },
  { id: "qc-263", domain: "renal", front: "HCM patient with Ca 13.5. Bridge to bisphosphonate?", back: "CALCITONIN 4 IU/kg SC/IM q12h — onset 2-6 hr. NOT mg-based dosing. Tachyphylaxis after 48-72 hr. Use for first 24-48 hr while bisphosphonate works", tags: ["renal"] },
  { id: "qc-264", domain: "renal", front: "Mg toxicity with respiratory depression in pre-eclamptic patient. Treatment?", back: "STOP mag infusion. CALCIUM GLUCONATE 1-2 g IV (or CaCl via central). Support airway. Mg antagonizes Ca at NMJ; Ca reverses", tags: ["renal"] },
  { id: "qc-265", domain: "renal", front: "Rhabdo patient with CK 50,000, urine pH 5.8. Bicarb?", back: "Routine bicarb NOT well supported; consider if severe acidosis (pH < 7.2) or refractory. Aggressive saline + UOP 200-300 mL/hr is mainstay", tags: ["renal"] },
  { id: "qc-266", domain: "renal", front: "Patient pre-CT with contrast, CrCl 35. Best CI-AKI prevention?", back: "IV ISOTONIC SALINE 1 mL/kg/hr × 6-12 hr before + after. NAC and bicarb are OBSOLETE per PRESERVE trial. Hold metformin × 48 hr after", tags: ["renal"] },
  { id: "qc-267", domain: "renal", front: "Patient on NSAIDs + ACEi + lasix presents with AKI. Mechanism?", back: "\"Triple whammy\" — NSAIDs constrict afferent arteriole, ACEi dilates efferent, diuretic reduces perfusion → hemodynamic AKI. Hold all 3 + restore volume", tags: ["renal"] },
  { id: "qc-268", domain: "renal", front: "Patient on vancomycin 3 weeks for endocarditis, AKI + rash + eosinophilia. Diagnosis?", back: "AIN — drug-induced interstitial nephritis. Stop vanc, switch to daptomycin or linezolid. Consider steroids if no improvement after stopping drug", tags: ["renal"] },
  { id: "qc-269", domain: "renal", front: "4 mm distal ureter stone causing pain. Outpatient management?", back: "Tamsulosin 0.4 mg daily × 4 wks (MET), ketorolac for pain (better than morphine for renal colic), follow-up imaging in 1-2 wks", tags: ["renal"] },
  { id: "qc-270", domain: "renal", front: "Kidney stone + obstruction + fever 39 + WBC 18K. Action?", back: "Urgent urology consult for DECOMPRESSION (ureteral stent or percutaneous nephrostomy). Broad-spectrum abx (Zosyn or ceftriaxone). IV fluids. This is OBSTRUCTED INFECTED SYSTEM — true urologic emergency", tags: ["renal"] },
  { id: "qc-271", domain: "renal", front: "Pregnant patient with cystitis, 1st trimester. Antibiotic choice?", back: "CEPHALEXIN or AUGMENTIN — safe throughout. AVOID Bactrim (1st trimester folate, 3rd trimester kernicterus). AVOID nitrofurantoin near term. Fluoroquinolones contraindicated", tags: ["renal"] },
  { id: "qc-272", domain: "renal", front: "Patient with uncomplicated pyelo can go home. Outpatient regimen?", back: "Ciprofloxacin 500 BID × 7d or levofloxacin 750 daily × 5d if low FQ resistance (<10%). Otherwise ceftriaxone 1g IV initial dose + oral cephalosporin or Bactrim. AVOID fosfomycin/nitrofurantoin — don't reach kidney", tags: ["renal"] },
  { id: "qc-273", domain: "renal", front: "Tolvaptan use for SIADH — important warning?", back: "BLACK BOX: hepatotoxicity. FDA limit 30 days. Monitor LFTs q1-3 days first month then monthly. Don't initiate if can't monitor", tags: ["renal"] },
  { id: "qc-274", domain: "renal", front: "RRT indications mnemonic?", back: "AEIOU: Acidosis (pH < 7.1), Electrolytes (K > 6.5), Ingestions (lithium, methanol, ethylene glycol, salicylates, theophylline, valproate, metformin), Overload (fluid), Uremia (pericarditis, bleeding, encephalopathy)", tags: ["renal"] },
  { id: "qc-275", domain: "tox", front: "Smoke inhalation patient with lactate 12, hypotension, AMS. Antidote?", back: "HYDROXOCOBALAMIN 5g IV over 15 min — safe in smoke inhalation. NOT sodium nitrite — would worsen O2 delivery if also CO-poisoned. NOT hydroxocobalamin for CO alone", tags: ["tox"] },
  { id: "qc-276", domain: "tox", front: "Mixed CO + CN smoke inhalation. Best initial antidote?", back: "Hydroxocobalamin — treats CN without making CO worse. 100% O2 ± HBO for CO. AVOID nitrites", tags: ["tox"] },
  { id: "qc-277", domain: "tox", front: "Salicylate level 95, pH 7.18, encephalopathic. Action?", back: "Hemodialysis indicated per EXTRIP. Continue bicarb infusion + K repletion as bridge. AVOID intubation if possible — if intubating, MUST match preintubation minute ventilation", tags: ["tox"] },
  { id: "qc-278", domain: "tox", front: "APAP ingestion 8 hr ago, level 200 mcg/mL at 4 hr. Action?", back: "Nomogram positive (probable toxicity at 4 hr if > 150). Start NAC immediately — IV protocol 150/50/100 mg/kg", tags: ["tox"] },
  { id: "qc-279", domain: "tox", front: "Late APAP presentation (24+ hr), AST 8000. Action?", back: "Start NAC regardless of level — continue until APAP undetectable + LFTs improving. Consult hepatology for King's College Criteria", tags: ["tox"] },
  { id: "qc-280", domain: "tox", front: "Iron tablet ingestion in 3 yo, asymptomatic, serum iron 600. Action?", back: "Likely safe to observe, deferoxamine indicated if symptomatic. Iron > 1000 = systemic toxicity threshold. WBI for visible tablets on KUB", tags: ["tox"] },
  { id: "qc-281", domain: "tox", front: "Sulfonylurea OD in elderly, glucose 35 → improves to 100 with D50. Disposition?", back: "Admit + OCTREOTIDE 50 mcg SC q6h × 24 hr. Dextrose alone causes rebound hypoglycemia by triggering more insulin release", tags: ["tox"] },
  { id: "qc-282", domain: "tox", front: "Metformin overdose, lactate 22, pH 6.95. Action?", back: "HEMODIALYSIS per EXTRIP — pH < 7.0 OR lactate > 20. Bicarb bridging", tags: ["tox"] },
  { id: "qc-283", domain: "tox", front: "SGLT2 patient presents with abdominal pain, glucose 220, anion gap 22, ketones 4+. Treatment?", back: "Euglycemic DKA — insulin infusion + D5NS to prevent hypoglycemia while shutting off ketogenesis. Don't be reassured by \"normal\" glucose", tags: ["tox"] },
  { id: "qc-284", domain: "tox", front: "TCA overdose with QRS 145, hypotension. Treatment sequence?", back: "Sodium bicarbonate 1-2 mEq/kg IV bolus → infusion targeting pH 7.45-7.55. Norepi for hypotension. Lipid emulsion for refractory. AVOID phenytoin, procainamide, physostigmine, flumazenil", tags: ["tox"] },
  { id: "qc-285", domain: "tox", front: "Bupropion OD with status epilepticus + wide QRS. Treatment?", back: "Benzos for seizures (avoid phenytoin), bicarb for QRS, ILE if refractory, ECMO for arrest", tags: ["tox"] },
  { id: "qc-286", domain: "tox", front: "Patient on phenelzine (MAOI) eats aged cheese, develops severe HTN + headache. Treatment?", back: "PHENTOLAMINE 5 mg IV (α-blocker). NITROPRUSSIDE alternative. AVOID pure BB (unopposed α). This is tyramine reaction / hypertensive crisis", tags: ["tox"] },
  { id: "qc-287", domain: "tox", front: "Patient on linezolid for VRE develops agitation, ankle clonus, hyperreflexia, T 39. Antidote?", back: "Serotonin syndrome from linezolid (MAOI) + something serotonergic [SSRI/SNRI/fentanyl/tramadol/dextromethorphan]. Stop offending agents, benzos, cyproheptadine 12 mg load → 2 mg q2h", tags: ["tox"] },
  { id: "qc-288", domain: "tox", front: "Verapamil OD with HR 35, BP 70/40, glucose 280. Treatment?", back: "Atropine often fails. Calcium 1g CaCl, fluids, NE/epi, HIE 1 u/kg bolus + infusion titrate to 10+ u/kg/hr, glucagon. Methylene blue for refractory vasoplegia. ECMO if arrest", tags: ["tox"] },
  { id: "qc-289", domain: "tox", front: "BB vs CCB OD glucose distinction?", back: "BB → HYPOglycemia (block β2 glycogenolysis). CCB → HYPERglycemia (block insulin release from β-cells via L-type Ca channel", tags: ["tox"] },
  { id: "qc-290", domain: "tox", front: "Child after teething gel applied to gums, SpO2 85% despite NRB, cyanotic, irritable. Diagnosis + treatment?", back: "Methemoglobinemia from benzocaine. Methylene blue 1-2 mg/kg IV over 5 min. Confirm G6PD status before", tags: ["tox"] },
  { id: "qc-291", domain: "tox", front: "Dig OD with K 6.5, bidirectional V-tach. Antidote?", back: "Dig-Fab empirically 10-20 vials IV. Insulin + dextrose for K. Calcium controversial but modern data shows safety. AVOID pacing (worsens arrhythmia in dig tox)", tags: ["tox"] },
  { id: "qc-292", domain: "tox", front: "Methanol level 80, anion gap 25, pH 7.18, vision change. Action?", back: "FOMEPIZOLE 15 mg/kg load + folate 50 mg q4-6h + HEMODIALYSIS — combination needed. Eyes are blind by time you can fix metabolic", tags: ["tox"] },
  { id: "qc-293", domain: "tox", front: "Sarin nerve agent exposure with seizures. Treatment?", back: "Atropine 2-6 mg IV doubling q5-10 min until secretions cleared + pralidoxime 1-2 g IV + midazolam 10 mg IM. Pralidoxime must be given BEFORE enzyme aging — soman ages in 2 min!", tags: ["tox"] },
  { id: "qc-294", domain: "tox", front: "Lithium level 4.5 in patient on lisinopril. Disposition?", back: "Hemodialysis indicated — Li > 4 regardless of symptoms. ACEi reduced clearance. AVOID loop diuretics. NS fluid rehydration. Watch for REBOUND elevation post-HD", tags: ["tox"] },
  { id: "qc-295", domain: "trauma", front: "Patient with severe TBI being intubated. Best induction agent?", back: "Etomidate 0.3 mg/kg — hemodynamically neutral, decreases CMRO2, maintains CPP. Ketamine acceptable per modern data. Propofol if no hypotension", tags: ["trauma"] },
  { id: "qc-296", domain: "trauma", front: "Severe TBI patient with HR 70, BP 100/60. Pre-intubation pharmacology to blunt sympathetic response?", back: "Fentanyl 2–3 mcg/kg IV ~3 min before intubation — DECREASES sympathetic response. Lidocaine no longer routine", tags: ["trauma"] },
  { id: "qc-297", domain: "trauma", front: "Patient with eclampsia + bradycardia needs intubation. Paralytic choice?", back: "ROCURONIUM — succinylcholine should be avoided in hyperK risk, peripartum (unknown muscle disease), severe sepsis. Rocuronium safe with sugammadex reversal available", tags: ["trauma"] },
  { id: "qc-298", domain: "trauma", front: "Patient with TBI on phenytoin develops purple glove syndrome from extravasation. Alternative AED for early PTS prophylaxis?", back: "Levetiracetam — now considered equivalent to phenytoin, increasingly first-line. 1g IV load", tags: ["trauma"] },
  { id: "qc-299", domain: "trauma", front: "ICH patient on warfarin, INR 4.5. Reversal?", back: "4F-PCC 35 u/kg + IV vitamin K 10 mg. NOT FFP first (slower, more volume)", tags: ["trauma"] },
  { id: "qc-300", domain: "trauma", front: "ICH on apixaban 5 mg BID, last dose 4 hr ago. Reversal?", back: "Andexanet alfa HIGH dose 800 mg bolus + 8 mg/min × 2 hr. If unavailable or contraindicated → 4F-PCC 50 u/kg", tags: ["trauma"] },
  { id: "qc-301", domain: "trauma", front: "Trauma patient receiving 8 units pRBC, iCal 0.8 mmol/L. Action?", back: "Calcium gluconate 1 g IV — citrate-induced hypoCa from massive transfusion. Empiric Ca repletion now favored in MT", tags: ["trauma"] },
  { id: "qc-302", domain: "trauma", front: "Penetrating chest trauma, pulseless. ACLS approach?", back: "NO CPR or epinephrine — resuscitative thoracotomy is the indicated emergency intervention", tags: ["trauma"] },
  { id: "qc-303", domain: "trauma", front: "TBI patient with GCS 12 within 2 hr of injury. TXA?", back: "YES — CRASH-3 showed benefit in GCS 9–15 (mild-moderate) within 3 hr. 1 g IV over 10 min + 1 g over 8 hr", tags: ["trauma"] },
  { id: "qc-304", domain: "trauma", front: "Trauma patient SBP 80, HR 130 on arrival, FAST positive abdominal fluid. ABC score 3. Initial resuscitation?", back: "Activate MT protocol — 1:1:1 plasma:platelets:RBC; max 1 L crystalloid then switch to blood. Consider LTOWB if available. TXA 1 g if within 3 hr", tags: ["trauma"] },
  { id: "qc-305", domain: "trauma", front: "Bilateral pupils 5 mm fixed in TBI patient, signs of herniation. Immediate pharm?", back: "23.4% NaCl 30 mL via central line OR 3% NaCl 250 mL bolus. Mannitol 1 g/kg alternative. Avoid steroids in TBI (CRASH trial showed harm)", tags: ["trauma"] },
  { id: "qc-306", domain: "trauma", front: "Cervical spinal cord injury C5, BP 75/45, HR 50. Diagnosis + treatment?", back: "Neurogenic shock — atropine for bradycardia, IV fluids + NOREPINEPHRINE (alpha + beta) — phenylephrine pure alpha would worsen reflex bradycardia. MAP goal 85–90 × 7 days", tags: ["trauma"] },
  { id: "qc-307", domain: "trauma", front: "Acute SCI within 8 hr of injury. Methylprednisolone?", back: "NO — AANS/CNS 2013 recommends AGAINST. NASCIS trials had methodological issues; harm signal", tags: ["trauma"] },
  { id: "qc-308", domain: "trauma", front: "Lateral canthotomy/cantholysis indication?", back: "Retrobulbar hemorrhage with orbital compartment syndrome — IOP > 40, decreased visual acuity, RAPD. Time-sensitive: vision loss within 90–120 min. Don't wait for pharm", tags: ["trauma"] },
  { id: "qc-309", domain: "trauma", front: "Pediatric trauma, 6 y/o, primary survey using which neuro scale?", back: "AVPU — Alert, Voice, Pain, Unresponsive — NOT APVU", tags: ["trauma"] },
  { id: "qc-310", domain: "trauma", front: "Burn patient day 5 needs intubation. Paralytic to AVOID?", back: "SUCCINYLCHOLINE — extrajunctional ACh receptors after burn day 1+ → exaggerated hyperK → arrest. Rocuronium safe", tags: ["trauma"] },
  { id: "qc-311", domain: "trauma", front: "Patient with retrobulbar hemorrhage from facial trauma, IOP 50. Acetazolamide allergy info?", back: "sulfonamide derivative — caution in sulfa allergy. Topical timolol + brimonidine + mannitol IV adjuncts AFTER lateral canthotomy", tags: ["trauma"] },
  { id: "qc-312", domain: "trauma", front: "Patient on buprenorphine 16 mg/day for OUD presents with trauma + severe pain. Pain management?", back: "CONTINUE buprenorphine; add full mu-agonist (higher doses needed due to receptor occupancy). Multimodal: APAP, ketorolac, ketamine, nerve blocks. Don't stop buprenorphine — withdrawal + worse pain", tags: ["trauma"] }
]);
